#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("USAGE\n");
        return 0;
    }

    char *str1 = argv[1];
    char *str2 = argv[2];

    int len1 = strlen(str1);
    int len2 = strlen(str2);

    if (len1 > 1024 || len2 > 1024) {
        printf("TOO_LONG\n");
        return 0;
    }

    int count1[256] = {0};
    int count2[256] = {0};

    for (int i = 0; i < len1; i++) {
        char c = tolower(str1[i]);
        if (c >= 'a' && c <= 'z') {
            count1[c - 'a']++;
        }
    }

    for (int i = 0; i < len2; i++) {
        char c = tolower(str2[i]);
        if (c >= 'a' && c <= 'z') {
            count2[c - 'a']++;
        }
    }

    int anagram = 1;
    for (int i = 0; i < 26; i++) {
        if (count1[i] != count2[i]) {
            anagram = 0;
            break;
        }
    }

    if (anagram) {
        printf("ANAGRAM\n");
    } else {
        printf("NOT_ANAGRAM\n");
    }

    return 0;
}
